#' Marginal Treatment Effects
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param instruments .
#' @param covs .
#' @param cluster .
#' @param degree .
#' @param link .
#' @param nboot .
#' @param level .
#' @param seed .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$support} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pars} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$tests} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$curve} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mtePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$psPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$support$asDF}
#'
#' \code{as.data.frame(results$support)}
#'
#' @export
ivmte <- function(
    data,
    outcome,
    treat,
    instruments,
    covs,
    cluster,
    degree = 2,
    link = "probit",
    nboot = 300,
    level = 95,
    seed = 1234,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ivmte requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(instruments)) instruments <- jmvcore::resolveQuo(jmvcore::enquo(instruments))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(instruments), instruments, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- ivmteOptions$new(
        outcome = outcome,
        treat = treat,
        instruments = instruments,
        covs = covs,
        cluster = cluster,
        degree = degree,
        link = link,
        nboot = nboot,
        level = level,
        seed = seed,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivmteClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

